Given a unsorted integer array arr[] and an integer K. The task is to count the number of subarray with exactly K Perfect Square Numbers. Examples:  



Input: arr[] = {2, 4, 9, 3}, K = 2 Output: 4 Explanation: Since total number of perfect square number in the array are 2. So the 4 subarrays with 2 perfect square number are: 1.{2, 4, 9} 2.{2, 4, 9, 3} 3.{4, 9} 4.{4, 9, 3}Input: arr[] = {4, 2, 5}, K = 3 Output: 0  



 



Simple Approach: Generate all the subarrays and count the number of perfect numbers in the given subarray if the count is equal to K increment the count for ans variable.Time Complexity: O(N2)Efficient Approach:  

Traverse the given array arr[] and check whether the element is Perfect Square or not.  If the current element is Perfect Square then change the value of array at that index to 1, Else change the value at that index to 0.  Now the given array is converted into Binary Array.  Now, Find the count of subarray with sum equals to K in the above Binary Array using the approach discussed in this article.  

Below is the implementation of the above approach. 



            C++

    // C++ program to Count of subarrays having
// exactly K perfect square numbers.

#include <bits/stdc++.h>
using namespace std;

// A utility function to check if
// the number n is perfect square
// or not
bool isPerfectSquare(long double x)
{
    // Find floating point value of
    // square root of x.
    long double sr = sqrt(x);

    // If square root is an integer
    return ((sr - floor(sr)) == 0);
}

// Function to find number of subarrays
// with sum exactly equal to k
int findSubarraySum(int arr[], int n, int K)
{
    // STL map to store number of subarrays
    // starting from index zero having
    // particular value of sum.
    unordered_map<int, int> prevSum;

    int res = 0;

    // To store the sum of element traverse
    // so far
    int currsum = 0;

    for (int i = 0; i < n; i++) {

        // Add current element to currsum
        currsum += arr[i];

        // If currsum = K, then a new
        // subarray is found
        if (currsum == K) {
            res++;
        }

        // If currsum > K then find the
        // no. of subarrays with sum
        // currsum - K and exclude those
        // subarrays
        if (prevSum.find(currsum - K)
            != prevSum.end())
            res += (prevSum[currsum - K]);

        // Add currsum to count of
        // different values of sum
        prevSum[currsum]++;
    }

    // Return the final result
    return res;
}

// Function to count the subarray with K
// perfect square numbers
void countSubarray(int arr[], int n, int K)
{
    // Update the array element
    for (int i = 0; i < n; i++) {

        // If current element is perfect
        // square then update the
        // arr[i] to 1
        if (isPerfectSquare(arr[i])) {
            arr[i] = 1;
        }

        // Else change arr[i] to 0
        else {
            arr[i] = 0;
        }
    }

    // Function Call
    cout << findSubarraySum(arr, n, K);
}

// Driver Code
int main()
{
    int arr[] = { 2, 4, 9, 2 };
    int K = 2;
    int N = sizeof(arr) / sizeof(arr[0]);

    // Function Call
    countSubarray(arr, N, K);
    return 0;
}



